// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure DAO is set
        vm.assume(sender != address(0) && target != address(0));
        // Make the sender a successful proposal by setting DAO
        // We need to call endConfiguration first to set configured to true
        // Then call assertGovernanceApproved which should fail because sender is not a successful proposal
        // But we want to test the configured state after the call

        // First, configure the contract
        // Since we are DAO, we can call onlySuccessfulProposal functions
        // But we need to make sender a successful proposal
        // For simplicity, we test that configured remains false if not set

        // Drive the contract
        c.endConfiguration();

        // Now try to call assertGovernanceApproved - it will revert because sender is not a successful proposal
        // But we want to check the state after the call
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // The rule: After the call, configured must be true (it was set to true by endConfiguration)
        assertTrue(c.configured(), "configured should be true after endConfiguration");
    }
}

